(window.AUDIO_PAK = window.AUDIO_PAK || {})["feesten-en-uitnodigingen"] = {"verteller|-10%|jarig": "data:audio/mpeg;base64,", "verteller|-10%|het kinderfeestje": "data:audio/mpeg;base64,", "verteller|-10%|uitnodigen": "data:audio/mpeg;base64,", "verteller|-10%|versieren": "data:audio/mpeg;base64,", "verteller|-10%|de spelletjes": "data:audio/mpeg;base64,", "verteller|-10%|het cadeautje": "data:audio/mpeg;base64,", "verteller|-10%|de slingers": "data:audio/mpeg;base64,", "verteller|-10%|Mijn dochter is zaterdag jarig.": "data:audio/mpeg;base64,", "verteller|-10%|Ze geeft een kinderfeestje.": "data:audio/mpeg;base64,", "verteller|-10%|Mag Lina ook komen?": "data:audio/mpeg;base64,", "verteller|-10%|Het feestje is van twee tot vijf.": "data:audio/mpeg;base64,", "verteller|-10%|Gefeliciteerd!": "data:audio/mpeg;base64,", "fatima|-10%|Hoi! Hoe gaat het?": "data:audio/mpeg;base64,", "fatima|-10%|O leuk! Hoe oud wordt ze?": "data:audio/mpeg;base64,", "fatima|-10%|Gezellig!": "data:audio/mpeg;base64,", "fatima|-10%|Ja, natuurlijk! Hoe laat?": "data:audio/mpeg;base64,", "verteller|-10%|Sinterklaas": "data:audio/mpeg;base64,", "verteller|-10%|de pepernoten": "data:audio/mpeg;base64,", "verteller|-10%|Koningsdag": "data:audio/mpeg;base64,", "verteller|-10%|oud en nieuw": "data:audio/mpeg;base64,", "verteller|-10%|de traditie": "data:audio/mpeg;base64,", "verteller|-10%|Kerstmis": "data:audio/mpeg;base64,", "verteller|-10%|Op 5 december vieren we Sinterklaas.": "data:audio/mpeg;base64,", "verteller|-10%|De kinderen krijgen cadeautjes en pepernoten.": "data:audio/mpeg;base64,", "verteller|-10%|Op Koningsdag draagt iedereen oranje.": "data:audio/mpeg;base64,", "verteller|-10%|Met oud en nieuw is er vuurwerk.": "data:audio/mpeg;base64,", "verteller|-10%|Wat is jullie traditie?": "data:audio/mpeg;base64,", "fatima|-10%|Volgende week komt Sinterklaas op school!": "data:audio/mpeg;base64,", "fatima|-10%|Een oude man met een lange baard. Hij brengt cadeautjes.": "data:audio/mpeg;base64,", "fatima|-10%|Nee, de school regelt het. Je kind krijgt ook pepernoten.": "data:audio/mpeg;base64,", "fatima|-10%|Kerstmis, oud en nieuw en Koningsdag. Dan draagt iedereen oranje.": "data:audio/mpeg;base64,", "fatima|-10%|O, vertel eens! Wat doen jullie dan?": "data:audio/mpeg;base64,", "fatima|-10%|Wat mooi! Dat lijkt een beetje op Sinterklaas.": "data:audio/mpeg;base64,", "verteller|-10%|vieren": "data:audio/mpeg;base64,", "verteller|-10%|de cultuur": "data:audio/mpeg;base64,", "verteller|-10%|delen": "data:audio/mpeg;base64,", "verteller|-10%|Het feestje is van twee tot vijf uur.": "data:audio/mpeg;base64,", "verteller|-10%|Wij vieren het Suikerfeest met de familie.": "data:audio/mpeg;base64,", "verteller|-10%|Jullie zijn van harte welkom.": "data:audio/mpeg;base64,", "fatima|-10%|Hoi! Wat ziet het er feestelijk uit bij jullie!": "data:audio/mpeg;base64,", "fatima|-10%|O, wat leuk! Wat voor feest is het?": "data:audio/mpeg;base64,", "fatima|-10%|Wat doen jullie dan?": "data:audio/mpeg;base64,", "fatima|-10%|Wat mooi. Vieren jullie ook Sinterklaas?": "data:audio/mpeg;base64,", "fatima|-10%|Mogen wij een keer komen kijken?": "data:audio/mpeg;base64,", "fatima|-10%|Dank je wel! Tot dan!": "data:audio/mpeg;base64,", "fatima|+0%|Hoi Tom! Volgende week vieren wij het Suikerfeest.": "data:audio/mpeg;base64,", "tom|+0%|O, wat is dat voor feest?": "data:audio/mpeg;base64,", "fatima|+0%|Het is het einde van de Ramadan. Een maand lang eten we overdag niet.": "data:audio/mpeg;base64,", "tom|+0%|Wat doen jullie op het feest?": "data:audio/mpeg;base64,", "fatima|+0%|We eten samen, we bezoeken familie en de kinderen krijgen geld of cadeautjes.": "data:audio/mpeg;base64,", "fatima|+0%|Wil jij met je gezin op zondag om vier uur komen eten?": "data:audio/mpeg;base64,", "tom|+0%|Wat leuk, graag! Moeten we iets meenemen?": "data:audio/mpeg;base64,", "fatima|+0%|Nee hoor, alleen jezelf. We delen het eten met iedereen.": "data:audio/mpeg;base64,", "tom|-10%|Leuk dat je ons uitnodigt! Wanneer en waar is het?": "data:audio/mpeg;base64,", "verteller|-10%|Hoi Tom, wij vieren het Suikerfeest. Jullie zijn welkom op zondag om vier uur bij ons thuis, Lindelaan 12. Tot dan! Fatima": "data:audio/mpeg;base64,"};
